const raw = $input.first().json;
const body = raw.body || raw;

const sessionId = body.session_id  || null;
const dealerId  = body.dealer_id   || null;
const event     = body.event       || 'message';
const message   = body.message     || '';
const language  = body.language    || 'es';

// Vehicle context (present on session_start)
const vehicle  = body.vehicle  || null;
const showroom = body.showroom || null;

if (!sessionId || !dealerId) {
  return [{ json: { _error: 'missing_session_or_dealer', sessionId, dealerId, event, message, language, vehicle, showroom } }];
}

return [{ json: { sessionId, dealerId, event, message, language, vehicle, showroom, _error: null } }];

const d = $input.first().json;
const v = d.vehicle  || {};
const s = d.showroom || {};
const lang = d.language || 'es';

const vehicleInfo = [
  v.title   ? `Vehículo: ${v.title}` : null,
  v.price && !v.price_on_request ? `Precio: ${new Intl.NumberFormat('es-ES', {style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v.price)}` : v.price_on_request ? 'Precio: A consultar' : null,
  v.year        ? `Año: ${v.year}` : null,
  v.fuel_type   ? `Combustible: ${v.fuel_type}` : null,
  v.mileage_km  ? `Kilómetros: ${new Intl.NumberFormat('es-ES').format(v.mileage_km)} km` : null,
  v.power_hp    ? `Potencia: ${v.power_hp} CV` : null,
].filter(Boolean).join('\n');

const showroomInfo = [
  s.name ? `Concesionario: ${s.name}` : null,
  s.city ? `Ciudad: ${s.city}` : null,
  s.whatsapp ? `WhatsApp: ${s.whatsapp}` : null,
].filter(Boolean).join('\n');

const systemPrompt = `Eres el asistente de ventas de ${s.name || 'este concesionario'} en Black Label Market, especializado en vehículos premium.

INFORMACIÓN DEL VEHÍCULO:
${vehicleInfo || 'No disponible'}

INFORMACIÓN DEL CONCESIONARIO:
${showroomInfo || 'No disponible'}

Tu objetivo:
1. Responder preguntas sobre el vehículo con información precisa
2. Entender las necesidades del comprador (uso, financiación, plazo de compra, vehículo a entregar)
3. Cuando el comprador muestre interés real, facilitar el contacto por WhatsApp o visita
4. Ser conciso (respuestas de 2-3 frases), profesional y cercano
5. Idioma: ${lang === 'es' ? 'Español' : lang}

NO inventes características del vehículo que no figuren arriba. Si no sabes algo, di que lo consultarás con el equipo.`;

const openingMessage = lang === 'es'
  ? `¡Hola! Soy el asistente de ${s.name || 'este concesionario'}. Estoy aquí para resolver tus dudas sobre ${v.title || 'este vehículo'} y ayudarte en lo que necesites. ¿Qué te gustaría saber?`
  : `Hi! I'm the assistant for ${s.name || 'this dealership'}. I'm here to answer your questions about ${v.title || 'this vehicle'}. What would you like to know?`;

return [{ json: { ...d, systemPrompt, openingMessages: [{ role: 'user', content: '(session_start)' }, { role: 'assistant', content: openingMessage }], openingMessage } }];

const input   = $('Switch por tipo de evento').first().json;
const rows    = $input.all();
const session = rows.length > 0 ? rows[0].json : null;

const history = (session?.messages || []);

// Build system prompt from last session_start context (first assistant message)
const vehicleContext = history.length > 0 && history[0]?.role === 'user'
  ? '' : '';

const systemPrompt = `Eres el asistente de ventas de un concesionario premium en Black Label Market.
Responde de forma concisa (2-3 frases), profesional y útil.
Si el comprador muestra interés real en comprar, sugiere contactar por WhatsApp o concertar visita.
NO inventes información que no tengas.`;

// Keep last 10 messages to avoid token overflow
const recentHistory = history.slice(-10);

const messages = [
  { role: 'system', content: systemPrompt },
  ...recentHistory,
  { role: 'user', content: input.message }
];

return [{ json: { ...input, messages, history } }];

const openaiResp = $input.first().json;
const prevData   = $('Construir request OpenAI').first().json;

const aiMessage = openaiResp?.choices?.[0]?.message?.content || 'Lo siento, no he podido procesar tu mensaje. Por favor, inténtalo de nuevo.';

const updatedHistory = [
  ...prevData.history,
  { role: 'user',      content: prevData.message },
  { role: 'assistant', content: aiMessage }
];

// Keep only last 20 messages to limit storage
const trimmedHistory = updatedHistory.slice(-20);

return [{ json: { ...prevData, aiMessage, updatedHistory: trimmedHistory } }];
